+package release
+
+import (
+	"context"
+	"errors"
+	"testing"
+
+	"github.com/google/go-github/v32/github"
+)
+
+func TestIs(t *testing.T) {
+	for _, tc := range []struct {
+		version string
+		want    bool
+	}{
+		{"", false},
+		{"dev", false},
+		{"1.2.3-dev", false},
+		{"1.2.3-snapshot", false},
+		{"1.2.3-rc", false},
+		{"1.2.3-rc.1", false},
+		{"v1.2.3", true},
+		{"1.2.3", true},
+	} {
+		t.Run(tc.version, func(t *testing.T) {
+			if got := Is(tc.version); got != tc.want {
+				t.Fatalf("Is(%q) = %t, want %t", tc.version, got, tc.want)
+			}
+		})
+	}
+}
+
+func TestCheck(t *testing.T) {
+	for _, tc := range []struct {
+		name, current, latest string
+		wantUpdate            bool
+	}{
+		{"newer available", "1.2.3", "v1.3.0", true},
+		{"running latest", "v1.3.0", "v1.3.0", false},
+		{"ahead of latest", "v1.4.0", "v1.3.0", false},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			info, err := check(context.Background(), tc.current, func(context.Context) (*github.RepositoryRelease, error) {
+				return &github.RepositoryRelease{TagName: github.String(tc.latest), HTMLURL: github.String("https://example.com/release")}, nil
+			})
+			if err != nil {
+				t.Fatal(err)
+			}
+			if info.CurrentVersion != tc.current || info.LatestVersion != tc.latest || info.UpdateAvailable != tc.wantUpdate || info.LatestVersionURL != "https://example.com/release" {
+				t.Fatalf("unexpected release info: %+v", info)
+			}
+		})
+	}
+}
+
+func TestCheckFailureKeepsCurrentVersion(t *testing.T) {
+	info, err := check(context.Background(), "1.2.3", func(context.Context) (*github.RepositoryRelease, error) {
+		return nil, errors.New("unavailable")
+	})
+	if err == nil || info.CurrentVersion != "1.2.3" || info.UpdateAvailable {
+		t.Fatalf("unexpected result: info=%+v err=%v", info, err)
+	}
+}

